VALUES
  (125, '¿Qué gas absorben las plantas durante la fotosíntesis?', 'Oxígeno', 'Nitrógeno', 'Dióxido de carbono', 'Helio', 'C', 'Ciencia', 'Fácil', 'Las plantas utilizan dióxido de carbono en la fotosíntesis.'),
  (126, '¿Qué fuerza mantiene a los planetas en órbita alrededor del Sol?', 'Magnetismo', 'Gravedad', 'Fricción', 'Electricidad', 'B', 'Ciencia', 'Fácil', 'La gravedad mantiene los cuerpos en órbita.'),
  (127, '¿Cuál es aproximadamente la velocidad de la luz en el vacío?', '300 km/s', '3.000 km/s', '300.000 km/s', '3.000.000 km/s', 'C', 'Ciencia', 'Medio', 'La luz viaja aproximadamente a 300.000 km/s en el vacío.'),
  (128, '¿Qué partícula tiene carga eléctrica negativa?', 'Protón', 'Neutrón', 'Electrón', 'Fotón', 'C', 'Ciencia', 'Fácil', 'El electrón tiene carga eléctrica negativa.'),
  (129, '¿Qué científico formuló las leyes del movimiento y la gravitación clásica?', 'Newton', 'Darwin', 'Pasteur', 'Faraday', 'A', 'Ciencia', 'Medio', 'Isaac Newton formuló las leyes del movimiento y la gravitación universal.'),
  (130, '¿Qué tipo de animal es una ballena?', 'Pez', 'Reptil', 'Mamífero', 'Anfibio', 'C', 'Ciencia', 'Fácil', 'Las ballenas son mamíferos marinos.'),
